create or replace function public.confirm_payment_and_allocate(p_payment_submission_id uuid,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_order public.presale_orders%rowtype; v_payment public.payment_submissions%rowtype; v_admin uuid:=auth.uid(); v_allocation public.dtr_allocations%rowtype; v_ref text:='ALLOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,20)); begin if v_admin is null or not exists(select 1 from public.admin_roles where user_id=v_admin and role in('ADMIN','SUPER_ADMIN','REVIEWER')) then raise exception 'ADMIN_AUTHORIZATION_REQUIRED' using errcode='42501'; end if; select * into v_payment from public.payment_submissions where id=p_payment_submission_id for update; if not found then raise exception 'PAYMENT_NOT_FOUND' using errcode='P0002'; end if; select * into v_order from public.presale_orders where id=v_payment.order_id for update; if not found then raise exception 'ORDER_NOT_FOUND' using errcode='P0002'; end if; if v_order.status in('CONFIRMED','DTR_ALLOCATED') or exists(select 1 from public.dtr_allocations where order_id=v_order.id) then raise exception 'ORDER_ALREADY_ALLOCATED' using errcode='23505'; end if; if v_order.status not in('UNDER_REVIEW','PAYMENT_SUBMITTED') then raise exception 'INVALID_ORDER_STATE' using errcode='P0001'; end if; update public.payment_submissions set status='VERIFIED',updated_at=now() where id=v_payment.id; update public.presale_orders set status='CONFIRMED',updated_at=now() where id=v_order.id; insert into public.payment_verifications(payment_submission_id,order_id,reviewer_id,status,reason) values(v_payment.id,v_order.id,v_admin,'CONFIRMED',p_reason); insert into public.dtr_allocations(order_id,investor_id,payment_submission_id,dtr_amount,allocation_reason,created_by) values(v_order.id,v_order.investor_id,v_payment.id,v_order.expected_dtr,coalesce(p_reason,'Verified payment'),v_admin) returning * into v_allocation; insert into public.allocation_ledger(allocation_id,investor_id,order_id,payment_submission_id,dtr_amount,reason,administrator_id,audit_reference) values(v_allocation.id,v_order.investor_id,v_order.id,v_payment.id,v_order.expected_dtr,coalesce(p_reason,'Verified payment'),v_admin,v_ref); insert into public.admin_actions(administrator_id,order_id,payment_submission_id,action,reason) values(v_admin,v_order.id,v_payment.id,'CONFIRM',p_reason); insert into public.audit_events(actor_id,event_type,order_id,payment_submission_id,allocation_id,audit_reference,metadata) values(v_admin,'PAYMENT_CONFIRMED_AND_ALLOCATED',v_order.id,v_payment.id,v_allocation.id,v_ref,jsonb_build_object('dtr_amount',v_order.expected_dtr,'idempotency_key',v_payment.id)); update public.presale_orders set status='DTR_ALLOCATED',updated_at=now() where id=v_order.id; return jsonb_build_object('order_id',v_order.id,'payment_submission_id',v_payment.id,'allocation_id',v_allocation.id,'dtr_amount',v_order.expected_dtr,'audit_reference',v_ref); exception when unique_violation then raise exception 'ALLOCATION_ALREADY_EXISTS' using errcode='23505'; end; $$;
revoke all on function public.confirm_payment_and_allocate(uuid,text) from public; grant execute on function public.confirm_payment_and_allocate(uuid,text) to authenticated;
